 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    wall_row = next((r for r, row in enumerate(grid)
                     if len(set(row)) == 1 and row[0] != 0), None)
    if wall_row is None:
        return [row[:] for row in grid]
    direction = 1 if wall_row == 0 else -1  # objects travel toward the wall
    wall_color = grid[wall_row][0]
    occupied = {(r, c) for r in range(h) for c in range(w)
                if grid[r][c] != 0 and r != wall_row}
    seen = set()
    pieces = []
    for start in sorted(occupied):
        if start in seen:
            continue
        color = grid[start[0]][start[1]]
        q = deque([start])
        seen.add(start)
        cells = []
        while q:
            r, c = q.popleft()
            cells.append((r, c))
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                p = (nr, nc)
                if p in occupied and p not in seen and grid[nr][nc] == color:
                    seen.add(p)
                    q.append(p)
        pieces.append({'cells': cells, 'color': color})

    # Repeatedly let the pieces closest to the barrier move first until settled.
    while True:
        moved = False
        pieces.sort(key=lambda p: direction * max(r for r, c in p['cells']), reverse=True)
        for p in pieces:
            own = set(p['cells'])
            other = {cell for q in pieces if q is not p for cell in q['cells']}
            shifted = [(r + direction, c) for r, c in p['cells']]
            if all(0 <= r < h and (r, c) not in other for r, c in shifted):
                p['cells'] = shifted
                moved = True
        if not moved:
            break

    out = [[0] * w for _ in range(h)]
    out[wall_row] = [wall_color] * w
    for p in pieces:
        for r, c in p['cells']:
            out[r][c] = p['color']
    return out
